package dev.aegis.review.adapters.rest;
import dev.aegis.review.application.api.ReviewInbox; import dev.aegis.shared.Actor; import io.swagger.v3.oas.annotations.*; import io.swagger.v3.oas.annotations.media.Schema; import io.swagger.v3.oas.annotations.tags.Tag; import java.time.Instant; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/reviews") @Tag(name="reviews")
public class ReviewController { private final ReviewInbox inbox; public ReviewController(ReviewInbox inbox){this.inbox=inbox;} @Schema(name="ReviewVersionRequest") public record VersionRequest(long expectedVersion){} @Schema(name="ReviewItemDto") public record ReviewItemDto(UUID id,String sourceKind,String sourceId,long sourceVersion,String category,String reason,String priority,String titleKey,Map<String,String> params,String linkType,String linkId,List<String> actions,String status,Instant createdAt,Instant updatedAt,long version){static ReviewItemDto from(ReviewInbox.Item i){return new ReviewItemDto(i.id(),i.sourceKind(),i.sourceId(),i.sourceVersion(),i.category(),i.reason(),i.priority(),i.titleKey(),i.params(),i.linkType(),i.linkId(),i.actions(),i.status(),i.createdAt(),i.updatedAt(),i.version());}}
 @GetMapping @Operation(operationId="listReviewItems",summary="List and reconcile the shared review inbox") public List<ReviewItemDto> list(Actor actor,@RequestParam(required=false)String status,@RequestParam(required=false)String category){return inbox.list(actor,status,category).stream().map(ReviewItemDto::from).toList();}
 @PostMapping("/{id}/dismiss") @Operation(operationId="dismissReviewItem",summary="Dismiss the notice without changing its source") public ReviewItemDto dismiss(Actor actor,@PathVariable UUID id,@RequestBody VersionRequest request){return ReviewItemDto.from(inbox.dismiss(actor,id,request.expectedVersion()));}
 @PostMapping("/{id}/actions/{action}") @Operation(operationId="actOnReviewItem",summary="Run an application-owned source action") public ReviewItemDto act(Actor actor,@PathVariable UUID id,@PathVariable String action,@RequestBody VersionRequest request){return ReviewItemDto.from(inbox.act(actor,id,action,request.expectedVersion()));}
}
